import { isAreaOwned } from './dlcOwnership';
import { useEffect, useState } from 'react';
import type { GameId, DlcId } from './pokemonData';
import { ALL_1025_SPECIES_NAMES } from './nationalDexSpeciesNames';

/**
 * Wild-encounter dataset generated by `scripts/fetchEncounters.mjs` from
 * PokéAPI and stored as a static bundle in `public/data/encounters.json`.
 * Shape: { [pokemonId]: { [gameId]: { [locationAreaName]: RawEncounterDetail[] } } }
 * Compact detail keys keep the payload small:
 *   m: method · c: chance % · l: [minLevel, maxLevel] · v: version[]
 */
/** Compact detail row straight from the JSON bundle. */
interface RawEncounterDetail {
  m: string;
  c: number;
  l: [number, number];
  v: string[];
  /** Optional encounter condition values (weather, time of day, swarms…). */
  cd?: string[];
}
/** Per game: location-area name → detail rows. */
export type RawGameEncounters = Record<string, RawEncounterDetail[]>;
export type EncounterDataset = Record<
  string,
  Partial<Record<GameId, RawGameEncounters>>
>;

export interface EncounterDetail {
  method: string;
  chance: number;
  minLevel: number;
  maxLevel: number;
  versions: string[];
  conditions: string[];
}
export interface EncounterArea {
  area: string;
  details: EncounterDetail[];
}

let cache: Promise<EncounterDataset | null> | null = null;

/** Lazy-load the encounter bundle once per session; null when unavailable. */
export function loadEncounterDataset(): Promise<EncounterDataset | null> {
  if (!cache) {
    cache = fetch('/data/encounters.json')
      .then((res) => (res.ok ? res.json() : null))
      .then((raw: unknown) => {
        if (!raw || typeof raw !== 'object') return null;
        return raw as EncounterDataset;
      })
      .catch(() => {
        cache = null; // allow retry on next call
        return null;
      });
  }
  return cache;
}

export function getEncountersForGame(
  dataset: EncounterDataset | null,
  pokemonId: number,
  gameId: GameId
): EncounterArea[] | null {
  if (!dataset) return null;
  const byGame = dataset[pokemonId];
  if (!byGame) return null;
  const raw = byGame[gameId];
  if (!raw) return null;
  const areas = Object.entries(raw).map(([area, details]) => ({
    area,
    details: details.map((d) => ({
      method: d.m,
      chance: d.c,
      minLevel: d.l[0],
      maxLevel: d.l[1],
      versions: d.v,
      conditions: d.cd ?? [],
    })),
  }));
  return areas.length > 0 ? areas : null;
}

/**
 * Encounter-condition families the UI surfaces (weather, time of day,
 * seasons, swarms, radar, honey trees, headbutt trees, contests, radio
 * channels, weekdays, Max Raid den rarity). Everything else (backlot slots,
 * item requirements, trade specifics, story flags…) stays stored but hidden.
 * Returns null for condition names that should not be displayed.
 */
export function prettyEncounterCondition(name: string): string | null {
  if (name.startsWith('weather-')) {
    const map: Record<string, string> = {
      'weather-normal': 'Any weather',
      'weather-fog': 'Fog',
      'weather-raining': 'Rain',
      'weather-thunderstorm': 'Thunderstorm',
      'weather-intense-sun': 'Intense sun',
      'weather-overcast': 'Overcast',
      'weather-snowing': 'Snowing',
      'weather-snowstorm': 'Snowstorm',
      'weather-sandstorm': 'Sandstorm',
      'weather-drought': 'Drought',
      'weather-rainstorm': 'Rainstorm',
    };
    return (
      map[name] ||
      name
        .replace('weather-', '')
        .split('-')
        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
        .join(' ')
    );
  }
  const exact: Record<string, string> = {
    'time-day': 'Daytime',
    'time-morning': 'Morning',
    'time-evening': 'Evening',
    'time-night': 'Night',
    'season-spring': 'Spring',
    'season-summer': 'Summer',
    'season-autumn': 'Autumn',
    'season-winter': 'Winter',
    'swarm-yes': 'Swarm',
    'radar-on': 'Poké Radar',
    'bug-catching-contest-yes': 'Bug-Catching Contest',
    'radio-hoenn': 'Hoenn Sound radio',
    'radio-sinnoh': 'Sinnoh Sound radio',
    'pla-alpha': 'Alpha form',
    'pla-mass-outbreak': 'Mass Outbreak',
    'sv-mass': 'Mass outbreak nearby',
  };
  if (exact[name]) return exact[name];
  if (name.startsWith('trade-')) {
    const wanted = name.slice('trade-'.length);
    if (wanted === 'any-pokemon') return 'NPC accepts any Pokémon';
    return `NPC wants: ${prettyEncounterWantedSpecies(wanted)}`;
  }
  if (name.startsWith('sv-biome-')) {
    const biome = name.replace('sv-biome-', '').split('-').map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    return `Biome: ${biome}`;
  }
  const prefix = (p: string, fmt: (rest: string) => string): string | null =>
    name.startsWith(p) ? fmt(name.slice(p.length)) : null;
  return (
    prefix('honey-tree-group-', (r) => `Honey tree (group ${r.toUpperCase()})`) ||
    prefix('headbutt-tree-', (r) => `Headbutt tree (${r})`) ||
    prefix('weekday-', (r) => `${r.charAt(0).toUpperCase() + r.slice(1)}s only`) ||
    prefix('max-den-rarity-', (r) => `Max Den (${r})`) ||
    prefix('max-den-rating-', (r) => `Max Den ${r.replace('-star', '★')}`) ||
    null
  );
}


/**
 * Species the NPC asks for in an in-game trade, from a condition slug such as
 * "nidoran-m" or "meowth-galar". Uses the canonical dex names so spelling and
 * punctuation match the rest of the app, then falls back to title-casing.
 */
export function prettyEncounterWantedSpecies(slug: string): string {
  const known: Record<string, string> = {
    'nidoran-m': 'Nidoran♂',
    'nidoran-f': 'Nidoran♀',
  };
  if (known[slug]) return known[slug];
  // Regional forms use a "<species>-<region>" slug (e.g. meowth-galar).
  const region = slug.match(/-(alola|galar|hisui|paldea)$/);
  const baseSlug = region ? slug.slice(0, -region[0].length) : slug;
  const key = baseSlug.toLowerCase().replace(/[^a-z0-9]/g, '');
  let name: string | null = null;
  for (const info of Object.values(ALL_1025_SPECIES_NAMES)) {
    if (info?.name && info.name.toLowerCase().replace(/[^a-z0-9]/g, '') === key) {
      name = info.name;
      break;
    }
  }
  if (!name) {
    name = baseSlug
      .split('-')
      .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
      .join(' ');
  }
  if (!region) return name;
  const prefix: Record<string, string> = {
    alola: 'Alolan', galar: 'Galarian', hisui: 'Hisuian', paldea: 'Paldean',
  };
  return `${prefix[region[1]]} ${name}`;
}
export function prettyEncounterMethod(method: string): string {
  const map: Record<string, string> = {
    walk: 'Walking in grass',
    surf: 'Surfing',
    'old-rod': 'Old Rod fishing',
    'good-rod': 'Good Rod fishing',
    'super-rod': 'Super Rod fishing',
    'older-rod': 'Old Rod fishing',
    'npc-trade': 'In-game NPC trade',
    gift: 'Gift',
    'gift-egg': 'Received as Egg',
    trade: 'In-game trade',
    'level-up': 'Level-up spawn',
    'radio-east': 'Pokégear radio (east)',
    'radio-west': 'Pokégear radio (west)',
    'swarm': 'Swarm',
    headbutt: 'Headbutt tree',
    'headbutt-special': 'Headbutt tree (special)',
    'hidden-grotto': 'Hidden Grotto',
    'in-sky': 'Encountered in sky',
    'bug-contest': 'Bug-Catching Contest',
    'grass-special': 'Grass (special)',
    'grass-dark': 'Grass (dark patch)',
    'overworld-special': 'Overworld special spawn',
    'overworld-flying-special': 'Flying overworld spawn',
    'max-raid': 'Max Raid battles',
    'island-scan': 'Island Scan',
  };
  return (
    map[method] ||
    method
      .split('-')
      .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
      .join(' ')
  );
}

/** Fetch + cache the dataset for components. */
export function useEncounterDataset(): { dataset: EncounterDataset | null; loading: boolean } {
  const [dataset, setDataset] = useState<EncounterDataset | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let alive = true;
    loadEncounterDataset().then((data) => {
      if (alive) {
        setDataset(data);
        setLoading(false);
      }
    });
    return () => {
      alive = false;
    };
  }, []);

  return { dataset, loading };
}

// ──────────────────────────────────────────────────────────────────────
// ENCOUNTER SUMMARY — correct, verified per-game "Where to find" text
// ──────────────────────────────────────────────────────────────────────

/**
 * Display names for area stems whose source spelling is concatenated
 * (Serebii Pokearth SV/PLA pages, e.g. "crimsonmirelands"). PokéAPI areas
 * already use hyphens and prettify generically.
 */
const AREA_DISPLAY_NAMES: Record<string, string> = {
  // ── Hisui (Legends: Arceus) ──
  obsidianfieldlands: 'Obsidian Fieldlands',
  crimsonmirelands: 'Crimson Mirelands',
  cobaltcoastlands: 'Cobalt Coastlands',
  coronethighlands: 'Coronet Highlands',
  alabastericelands: 'Alabaster Icelands',
  // ── Paldea (Scarlet/Violet) ──
  areazero: 'Area Zero',
  greatcraterofpaldea: 'Great Crater of Paldea',
  alfornadacavern: 'Alfornada Cavern',
  asadodesert: 'Asado Desert',
  casseroyalake: 'Casseroya Lake',
  dalizapapassage: 'Dalizapa Passage',
  eastpaldeansea: 'East Paldean Sea',
  westpaldeansea: 'West Paldean Sea',
  northpaldeansea: 'North Paldean Sea',
  southpaldeansea: 'South Paldean Sea',
  glaseadomountain: 'Glaseado Mountain',
  inletgrotto: 'Inlet Grotto',
  pocopath: 'Poco Path',
  pokemonleague: 'Pokémon League',
  socarrattrail: 'Socarrat Trail',
  tagtreethicket: 'Tagtree Thicket',
  eastprovinceareaone: 'East Province (Area One)',
  eastprovinceareatwo: 'East Province (Area Two)',
  eastprovinceareathree: 'East Province (Area Three)',
  westprovinceareaone: 'West Province (Area One)',
  westprovinceareatwo: 'West Province (Area Two)',
  westprovinceareathree: 'West Province (Area Three)',
  northprovinceareaone: 'North Province (Area One)',
  northprovinceareatwo: 'North Province (Area Two)',
  northprovinceareathree: 'North Province (Area Three)',
  southprovinceareaone: 'South Province (Area One)',
  southprovinceareatwo: 'South Province (Area Two)',
  southprovinceareathree: 'South Province (Area Three)',
  southprovinceareafour: 'South Province (Area Four)',
  southprovinceareafive: 'South Province (Area Five)',
  southprovinceareasix: 'South Province (Area Six)',
};

/** Human-readable location-area name (e.g. "kanto-route-1-area" → "Kanto Route 1"). */
export function prettifyAreaName(area: string): string {
  const curated = AREA_DISPLAY_NAMES[area];
  if (curated) return curated;
  return area
    .replace(/-/g, ' ')
    .replace(/\s+area$/, '')
    .replace(/\b\w/g, (c) => c.toUpperCase())
    .replace(/\bMt\b/g, 'Mt.')
    .replace(/\bPok(e|é)mon\b/g, 'Pokémon')
    .replace(/\bRoute\b (\d)/g, 'Route $1');
}

/**
 * Correct, verified per-game encounter summary derived from the PokéAPI /
 * Serebii-sourced bundle: the top areas with method, level range and
 * encounter chance. Returns null when the bundle has no rows for this
 * species × game (callers fall back to their curated text).
 */
export function summarizeEncountersForGame(
  dataset: EncounterDataset | null,
  pokemonId: number,
  gameId: GameId,
  ownedDlcs: readonly DlcId[] = []
): string | null {
  if (!dataset) return null;
  const raw = dataset[pokemonId]?.[gameId];
  if (!raw) return null;
  const areas = Object.entries(raw).filter(([area]) => isAreaOwned(gameId, area, ownedDlcs));
  if (areas.length === 0) return null;

  const parts = areas.slice(0, 3).map(([area, rows]) => {
    const methods = [...new Set(rows.map((r) => prettyEncounterMethod(r.m)))];
    const lvMin = Math.min(...rows.map((r) => r.l[0]));
    const lvMax = Math.max(...rows.map((r) => r.l[1]));
    const chance = Math.max(...rows.map((r) => r.c));
    const lv = lvMin === lvMax ? `Lv ${lvMin}` : `Lv ${lvMin}–${lvMax}`;
    const methodText =
      methods.length > 1 ? `${methods.slice(0, 2).join(' / ')}…` : (methods[0] ?? 'Wild');
    return `${prettifyAreaName(area)} — ${methodText} (${lv}${chance > 0 ? `, ${chance}%` : ''})`;
  });
  const more = areas.length - parts.length;
  return more > 0 ? `${parts.join(' · ')} + ${more} more area${more === 1 ? '' : 's'}` : parts.join(' · ');
}
